@import "./styles/base.css";


/* Client cabinet: the greeting card opens the profile modal. */
.profileTabbedPage.clientCorePageCabinet[data-profile-tab="cabinet"] .profileAiHeroButton {
  cursor: pointer !important;
  outline: none !important;
  position: relative !important;
  padding-right: 48px !important;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease !important;
}

.profileTabbedPage.clientCorePageCabinet[data-profile-tab="cabinet"] .profileAiHeroButton::after {
  content: "›" !important;
  position: absolute !important;
  right: 20px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: rgba(255, 255, 255, 0.48) !important;
  font-size: 30px !important;
  font-weight: 700 !important;
  line-height: 1 !important;
}

.profileTabbedPage.clientCorePageCabinet[data-profile-tab="cabinet"] .profileAiHeroButton:focus-visible {
  border-color: rgba(145, 173, 78, 0.48) !important;
  box-shadow: 0 0 0 3px rgba(145, 173, 78, 0.12) !important;
}

.profileTabbedPage.clientCorePageCabinet[data-profile-tab="cabinet"] .profileAiHeroButton:active {
  transform: scale(0.992) !important;
}

html:root[data-app-theme="warm-light"] body #root
  .profileTabbedPage.clientCorePageCabinet[data-profile-tab="cabinet"]
  .profileAiHeroButton::after {
  color: #737b91 !important;
}


/* LOGIN */
.loginPage {
  min-height: 100vh;
  width: 100%;
  padding: 32px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 28px;
}

.loginHero {
  width: 100%;
  text-align: center;
}

.appLogo {
  width: 78px;
  height: 78px;
  margin: 0 auto 16px;
  border-radius: 24px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #10120f;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36px;
  font-weight: 900;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.38);
}

.loginHero h1 {
  margin: 0;
  font-size: 44px;
  font-weight: 900;
  letter-spacing: -1px;
  color: var(--text);
}

.loginHero p {
  margin: 8px 0 0;
  color: var(--muted);
}

.loginCard {
  width: 100%;
  max-width: 390px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 28px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.28);
}

.loginCard h2 {
  margin: 0 0 8px;
  text-align: center;
  font-size: 26px;
}

.loginCard input,
.exercise input {
  width: 100%;
  padding: 15px;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: #090b09;
  color: var(--text);
  font-size: 16px;
  outline: none;
  appearance: none;
  -webkit-appearance: none;
}

.loginCard input:focus,
.exercise input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(127, 159, 58, 0.1);
}

.passwordBox {
  position: relative;
  width: 100%;
}

.passwordBox input {
  padding-right: 60px;
}

.eyeBtn {
  display: flex;
  align-items: center;
  justify-content: center;

  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);

  width: 42px;
  height: 42px;
  padding: 0;

  background: transparent;
  border: none;
  box-shadow: none;

  color: var(--muted);
  font-size: 22px;
  cursor: pointer;
}

.loginBtn,
.loginCard .loginBtn {
  width: 100%;
  min-height: 72px;
  margin-top: 6px;
  padding: 18px;
  border: none;
  border-radius: 22px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #10120f;
  font-size: 22px;
  font-weight: 900;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  box-shadow: none;
}

.loginBtn:active {
  transform: scale(0.98);
}

.loginError {
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(212, 90, 90, 0.12);
  color: #d97979;
  text-align: center;
  font-size: 14px;
}

.loginHint {
  margin: 0;
  text-align: center;
  color: #737a73;
  font-size: 13px;
}

/* MENU */
.menuPage {
  min-height: 100vh;
  padding: 56px 18px 32px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at top, #182018 0%, #070a08 55%);
}

.menuTitle,
.workoutTitle {
  font-size: clamp(34px, 9vw, 52px);
  font-weight: 900;
  text-align: center;
  margin: 0 0 28px;
  color: #fff;
  line-height: 1.05;
  letter-spacing: -1px;
}

.menuTitle::after,
.workoutTitle::after {
  content: "";
  display: block;
  width: 74px;
  height: 5px;
  margin: 22px auto 0;
  border-radius: 999px;
  background: #7ca33d;
  opacity: 0.9;
}

.menuButtons {
  width: 100%;
  max-width: 430px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.bigButton {
  width: 100%;
  min-height: 82px;
  padding: 18px 20px;
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: linear-gradient(180deg, #171c18 0%, #111511 100%);
  color: #fff;
  cursor: pointer;
  text-align: center;
  font-size: clamp(22px, 6vw, 30px);
  font-weight: 800;
  line-height: 1.18;
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.28);
}

.bigButton:active {
  transform: scale(0.98);
  opacity: 0.9;
}

.dayTitle {
  display: block;
  font-size: 22px;
  font-weight: 800;
}

.daySub {
  display: block;
  margin-top: 4px;
  font-size: 18px;
  font-weight: 600;
  opacity: 0.7;
}

.logoutSmall,
.backBtn {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #aaa;
  padding: 12px 22px;
  border-radius: 999px;
  cursor: pointer;
  font-size: 16px;
  font-weight: 800;
}

.logoutSmall {
  display: block;
  margin: 34px auto 0;
  padding: 14px 28px;
}

/* APP */
.app {
  max-width: 560px;
  min-height: 100vh;
  margin: 0 auto;

  padding-top: max(34px, calc(env(safe-area-inset-top) + 22px));
  padding-left: 14px;
  padding-right: 14px;
  padding-bottom: 22px;

  background: var(--bg);
}

.workoutHeader {
  text-align: center;
  margin-bottom: 8px;
}

.workoutHeaderCompact {
  width: 100%;
  max-width: 460px;
  margin: 0 auto 14px;

  display: grid;
  grid-template-columns: 56px 1fr 56px;
  align-items: center;
  gap: 0;
}

.backIconBtn {
  width: 46px;
  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.04);
  color: rgba(255, 255, 255, 0.82);

  font-size: 28px;
  font-weight: 700;

  cursor: pointer;
  justify-self: start;
}

.backIconBtn:active {
  transform: scale(0.96);
}

.app .workoutTitle,
.app .workoutTitleInline {
  margin: 0 !important;

  font-size: 18px !important;
  font-weight: 900 !important;

  color: rgba(255, 255, 255, 0.88) !important;

  text-align: center !important;

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  line-height: 1.25 !important;
  padding-top: 2px;
  padding-bottom: 2px;
}

.app .workoutTitle::after,
.app .workoutTitleInline::after {
  display: none !important;
}

.backBtn {
  margin-bottom: 18px;
}

.exercise,
.historyCard {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 28px;
  padding: 22px;
  margin-bottom: 22px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.22);
}

.exercise h3 {
  text-align: center;
  font-size: 25px;
  margin: 6px 0 22px;
  line-height: 1.2;
}

.exercise button,
.showVideoBtn {
  width: 100%;
  padding: 16px;
  border-radius: 18px;
  border: none;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #10120f;
  cursor: pointer;
  font-size: 17px;
  font-weight: 900;
  box-shadow: none;
}

.showVideoBtn {
  margin-bottom: 12px;
}

.exerciseVideo {
  width: 100%;
  max-height: 160px;
  border-radius: 18px;
  margin-bottom: 10px;
  background: #000;
  object-fit: cover;
}

.exercise input {
  font-size: 20px;
}

.previousInfo,
.previousInfo.subtle {
  display: block;
  width: 100%;
  margin: 6px 0 12px;
  color: rgba(244, 246, 242, 0.44);
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
}

/* EXERCISE CARDS + SWIPE */
.exerciseDeck {
  width: 100%;
  max-width: 460px;
  height: calc(100vh - 96px);
  min-height: 0;
  margin: 0 auto;
  padding: 0 12px 18px;

  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  gap: 12px;

  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  user-select: none;

  scrollbar-width: none;
}

.exerciseDeck::-webkit-scrollbar {
  display: none;
}

.exerciseCounter {
  width: 100%;
  max-width: 420px;
  text-align: center;
  color: rgba(255, 255, 255, 0.42);
  font-size: 12px;
  font-weight: 800;
  margin: 0;
  flex-shrink: 0;
}

.swipeHint,
.swipeBottomHint {
  width: 100%;
  max-width: 420px;
  min-height: 54px;
  padding: 8px 14px;
  border-radius: 16px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-top: 2px;
  margin-bottom: 10px;

  background: rgba(255, 255, 255, 0.035);
  color: rgba(255, 255, 255, 0.34);

  font-size: 13px;
  font-weight: 800;
  line-height: 1.25;
  text-align: center;

  flex-shrink: 0;
}

.swipeBottomHint {
  min-height: 26px;
  background: transparent;
  color: rgba(255, 255, 255, 0.3);
  margin-bottom: 4px;
}

.exerciseNavBtn {
  display: none;
}

.exerciseSlideCard {
  width: 100%;
  max-width: 420px;

  flex-shrink: 0;

  padding: 16px 18px 18px;
  border-radius: 30px;

  display: flex;
  flex-direction: column;

  overflow: visible;
  max-height: none;

  will-change: transform, opacity;
  backface-visibility: hidden;
  transform: translateZ(0);

  animation-duration: 560ms;
  animation-fill-mode: both;
  animation-timing-function: cubic-bezier(0.22, 0.9, 0.32, 1);
}

.exerciseSlideCard::-webkit-scrollbar {
  display: none;
}

.exerciseSlideCard.slideFromBottom {
  animation-name: cardNext;
}

.exerciseSlideCard.slideFromTop {
  animation-name: cardPrev;
}

/* следующее упражнение */
@keyframes cardNext {
  0% {
    opacity: 0;
    transform: translate3d(0, 42px, 0);
  }

  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

/* предыдущее упражнение */
@keyframes cardPrev {
  0% {
    opacity: 0;
    transform: translate3d(0, -42px, 0);
  }

  100% {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

.exerciseSlideCard h3 {
  font-size: 22px;
  line-height: 1.12;
  margin-bottom: 14px;
}

.setRow {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 9px;
}

.setRow input {
  height: 50px;
  border-radius: 16px;
  font-size: 22px;
  text-align: center;
}

.exerciseSlideCard button:not(.showVideoBtn) {
  min-height: 50px;
  border-radius: 18px;
  font-size: 17px;
}

.showVideoBtn {
  position: sticky;
  top: 0;
  z-index: 5;
}

.exerciseSlideCard button:not(.showVideoBtn) {
  position: sticky;
  bottom: 0;
  z-index: 5;
}

/* FINISH BUTTON */
.bottomBar {
  display: none;
}

.finishWorkoutCard {
  width: 100%;
  max-width: 420px;
  min-height: 106px;

  padding: 20px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 6px;

  border-radius: 28px;
  border: 1px solid rgba(127, 159, 58, 0.35);

  background: linear-gradient(180deg, #171c18 0%, #111511 100%);

  color: #fff;

  cursor: pointer;
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.28);
}

.finishWorkoutCard:active:not(:disabled) {
  transform: scale(0.98);
}

.finishWorkoutCard:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.finishWorkoutIcon {
  font-size: 28px;
  line-height: 1;
}

.finishWorkoutText {
  font-size: 23px;
  font-weight: 900;
  line-height: 1.1;
}

.finishWorkoutSubtext {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.42);
}

/* HISTORY */
.historyCard {
  padding: 0;
  overflow: hidden;
}

.historyCardHeader {
  width: 100%;
  padding: 20px;
  background: transparent;
  border: none;
  color: var(--text);
  display: flex;
  justify-content: space-between;
  align-items: center;
  text-align: left;
  font-size: 18px;
  font-weight: 900;
  cursor: pointer;
}

.historyCardHeader strong {
  font-size: 30px;
  color: var(--accent);
}

.historyCardBody {
  padding: 0 16px 16px;
}

.historyExercise {
  display: block;
  width: 100%;
  background: #101310;
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 16px;
  margin-top: 12px;
}

.historyExercise h4 {
  margin: 0 0 12px;
  font-size: 18px;
  color: var(--text);
  text-align: left;
}

.historySets {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
}

.historySet {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid #272d27;
  margin: 0;
}

.historySet span {
  color: var(--muted);
}

.historySet strong {
  color: var(--accent);
  white-space: nowrap;
}

/* SAVE TOAST */
.saveOverlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  z-index: 9998;
  animation: fadeIn 0.3s ease;
}

.saveToast {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0.95);
  z-index: 9999;

  width: 280px;
  padding: 28px 24px;
  border-radius: 26px;

  background: rgba(18, 22, 18, 0.95);
  border: 1px solid rgba(124, 163, 61, 0.4);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);

  backdrop-filter: blur(18px);

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;

  animation: saveToastIn 0.35s ease forwards,
    saveToastOut 0.35s ease 1.9s forwards;
}

.saveToastIcon {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: rgba(124, 163, 61, 0.25);
  color: #b8e66b;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  font-size: 28px;
}

.saveToastText {
  color: rgba(255, 255, 255, 0.85);
  font-size: 17px;
  font-weight: 600;
}

@keyframes saveToastIn {
  from {
    opacity: 0;
    transform: translate(-50%, -60%) scale(0.9);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

@keyframes saveToastOut {
  to {
    opacity: 0;
    transform: translate(-50%, -40%) scale(0.95);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* FINISH SCREEN */
.finishOverlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(10px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10000;
  animation: finishFadeIn 0.25s ease;
}

.finishCard {
  width: 84%;
  max-width: 330px;
  padding: 34px 24px 26px;
  border-radius: 30px;
  background: rgba(18, 22, 18, 0.96);
  border: 1px solid rgba(124, 163, 61, 0.35);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65);
  text-align: center;
  animation: finishScaleIn 0.35s ease;
}

.finishIcon {
  width: 72px;
  height: 72px;
  margin: 0 auto 18px;
  border-radius: 50%;
  background: rgba(124, 163, 61, 0.22);
  color: #b8e66b;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 38px;
  font-weight: 900;
}

.finishCard h2 {
  margin: 0;
  color: #fff;
  font-size: 26px;
  line-height: 1.15;
}

.finishCard p {
  margin: 12px 0 24px;
  color: rgba(255, 255, 255, 0.62);
  font-size: 16px;
  font-weight: 600;
}

.finishReturnBtn {
  width: 100%;
  height: 54px;
  border-radius: 18px;
  border: none;
  background: #7ca33d;
  color: #fff;
  font-size: 17px;
  font-weight: 800;
}

@keyframes finishFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes finishScaleIn {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.94);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* MOBILE */
@media (max-width: 700px) {
  .app {
    max-width: 100%;
    padding-top: max(34px, calc(env(safe-area-inset-top) + 22px));
    padding-left: 10px;
    padding-right: 10px;
    padding-bottom: 22px;
  }

  .menuTitle {
    font-size: 34px;
  }

  .exercise {
    padding: 16px;
  }

  .exercise h3 {
    font-size: 22px;
  }

  .loginHero h1 {
    font-size: 38px;
  }
}

@media (max-width: 480px) {
  .menuPage {
    padding-top: 48px;
  }

  .bigButton {
    min-height: 78px;
    padding: 16px 18px;
    border-radius: 24px;
  }

  .menuButtons {
    gap: 14px;
  }

  .exerciseDeck {
    height: calc(100vh - 96px);
    padding-left: 12px;
    padding-right: 12px;
    padding-bottom: 18px;
    gap: 12px;
  }

  .exerciseSlideCard {
    max-height: none;
    overflow: visible;
    padding: 14px 18px;
  }

  .exerciseSlideCard h3 {
    font-size: 21px;
    margin-bottom: 12px;
  }

  .exerciseVideo {
    max-height: 145px;
  }

  .setRow input {
    height: 48px;
  }
}

/* FINISH SUMMARY SLIDE */
.finishSlideWrap {
  width: 100%;
  max-width: 420px;
  flex-shrink: 0;

  display: flex;
  flex-direction: column;
  gap: 18px;

  will-change: transform, opacity;
  backface-visibility: hidden;
  transform: translateZ(0);

  animation-duration: 560ms;
  animation-fill-mode: both;
  animation-timing-function: cubic-bezier(0.22, 0.9, 0.32, 1);
}

.finishSlideWrap.slideFromBottom {
  animation-name: cardNext;
}

.finishSlideWrap.slideFromTop {
  animation-name: cardPrev;
}

.finishSummaryCard {
  min-height: auto;
  padding: 28px 22px 24px;

  align-items: center;
  text-align: center;

  background: linear-gradient(180deg, #171c18 0%, #111511 100%);
  border: 1px solid rgba(127, 159, 58, 0.28);
}

.finishSummaryCard .finishWorkoutIcon {
  width: 64px;
  height: 64px;
  margin-bottom: 10px;
  border-radius: 18px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: rgba(127, 159, 58, 0.22);
  color: #10120f;

  font-size: 34px;
  line-height: 1;
}

.finishSummaryCard h3 {
  margin: 4px 0 8px;
  font-size: 29px;
  line-height: 1.08;
}

.finishSummaryCard p {
  max-width: 330px;
  margin: 0 0 20px;
  color: rgba(255, 255, 255, 0.48);
  font-size: 15px;
  font-weight: 800;
  line-height: 1.35;
}

.finishStatsGrid {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.finishStatBox {
  min-height: 86px;
  padding: 14px 10px;
  border-radius: 20px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;

  background: #090b09;
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.finishStatBox span {
  color: rgba(255, 255, 255, 0.38);
  font-size: 14px;
  font-weight: 900;
}

.finishStatBox strong {
  color: #fff;
  font-size: 23px;
  font-weight: 900;
}

.finishWorkoutButton {
  width: 100%;
  min-height: 78px;
  padding: 18px 20px;
  border-radius: 28px;
  border: none;

