    radial-gradient(circle at 50% 58%, rgba(127, 159, 58, 0.08) 0%, transparent 42%),
    linear-gradient(180deg, #0e140e 0%, #050805 100%);

  color: var(--text);
  overflow: hidden;
}

.splashInner {
  width: min(78vw, 360px);
  min-height: 360px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  padding: 34px 24px;
  border-radius: 38px;

  background:
    linear-gradient(180deg, rgba(23, 30, 23, 0.72) 0%, rgba(9, 12, 9, 0.42) 100%);

  border: 1px solid rgba(127, 159, 58, 0.16);

  box-shadow:
    0 28px 80px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);

  position: relative;
}

.splashInner::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.055), transparent 36%);
  pointer-events: none;
}

.splashMark {
  width: 86px;
  height: 86px;
  margin-bottom: 18px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 28px;

  background:
    linear-gradient(180deg, rgba(127, 159, 58, 0.24), rgba(127, 159, 58, 0.11));

  border: 1px solid rgba(127, 159, 58, 0.22);

  font-size: 42px;

  box-shadow:
    0 14px 34px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.splashEmojis {
  display: none;
}

.splashLogo {
  color: var(--accent);
  font-size: clamp(82px, 22vw, 122px);
  font-weight: 900;
  line-height: 0.92;
  letter-spacing: 5px;
  text-shadow: 0 18px 46px rgba(0, 0, 0, 0.55);
}

.splashText {
  margin-top: 14px;
  color: rgba(255, 255, 255, 0.5);
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.3px;
}

.splashProgress {
  width: 100%;
  height: 9px;
  margin-top: 28px;

  overflow: hidden;
  border-radius: 999px;

  background: rgba(255, 255, 255, 0.075);
  border: 1px solid rgba(255, 255, 255, 0.035);
}

.splashProgress span {
  display: block;
  width: 42%;
  height: 100%;

  border-radius: 999px;

  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  box-shadow: 0 0 22px rgba(127, 159, 58, 0.38);
  animation: splashLoading 1.2s ease-in-out infinite;
}

.splashDots {
  display: flex;
  gap: 8px;
  margin-top: 18px;
}

.splashDots i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(145, 173, 78, 0.8);
  animation: splashDot 1.1s ease-in-out infinite;
}

.splashDots i:nth-child(2) {
  animation-delay: 0.16s;
}

.splashDots i:nth-child(3) {
  animation-delay: 0.32s;
}

@keyframes splashLoading {
  0% {
    transform: translateX(-115%);
  }

  55% {
    transform: translateX(95%);
  }

  100% {
    transform: translateX(245%);
  }
}

@keyframes splashDot {
  0%, 100% {
    opacity: 0.32;
    transform: translateY(0) scale(0.86);
  }

  50% {
    opacity: 1;
    transform: translateY(-3px) scale(1);
  }
}

