/* APP THEME SWITCHER */
:root,
:root[data-app-theme="dark-green"] {
  color-scheme: dark;
  --bg: #0d0f0d;
  --card: #171a17;
  --card-2: #1d211d;
  --line: #2b302b;
  --text: #f4f6f2;
  --muted: #8f968f;
  --accent: #7f9f3a;
  --accent-2: #91ad4e;
  --theme-menu-bg: radial-gradient(circle at top, #182018 0%, #070a08 55%);
  --theme-button-bg: linear-gradient(180deg, #171c18 0%, #111511 100%);
  --theme-button-text: #ffffff;
  --theme-subtle-panel: rgba(255, 255, 255, 0.04);
}

:root[data-app-theme="warm-light"] {
  color-scheme: light;
  --bg: #f7efd7;
  --card: #fff8e5;
  --card-2: #f3e6bc;
  --line: rgba(91, 70, 28, 0.16);
  --text: #211b12;
  --muted: #7d6a45;
  --accent: #f0c94f;
  --accent-2: #ffdf75;
  --danger: #c24d4d;
  --success: #6f8f31;
  --theme-menu-bg:
    radial-gradient(circle at top, rgba(255, 221, 112, 0.48) 0%, transparent 46%),
    linear-gradient(180deg, #fff7df 0%, #f1dfaa 100%);
  --theme-button-bg: linear-gradient(180deg, #fffaf0 0%, #f6e8bd 100%);
  --theme-button-text: #231b10;
  --theme-subtle-panel: rgba(35, 27, 16, 0.045);
}

.themeSwitchBtn {
  position: fixed;
  top: max(18px, calc(env(safe-area-inset-top) + 12px));
  right: 18px;
  z-index: 1200;

  width: 46px;
  height: 46px;
  padding: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.055);
  color: var(--text);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.26);
  cursor: pointer;
  transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease;
}

.themeSwitchBtn span {
  font-size: 21px;
  line-height: 1;
}

.themeSwitchBtn:active {
  transform: scale(0.94);
}

:root[data-app-theme="warm-light"] .themeSwitchBtn {
  border-color: rgba(91, 70, 28, 0.14);
  background: rgba(255, 250, 235, 0.72);
  box-shadow: 0 12px 30px rgba(104, 78, 23, 0.18);
}

:root[data-app-theme="warm-light"] body,
:root[data-app-theme="warm-light"] .app {
  background: var(--bg);
  color: var(--text);
}

.menuPage {
  background: var(--theme-menu-bg);
  transition: background 0.22s ease, color 0.22s ease;
}

.menuPage .menuTitle {
  color: var(--text);
}

.menuPage .bigButton {
  background: var(--theme-button-bg);
  color: var(--theme-button-text);
  border-color: var(--line);
  transition: background 0.22s ease, color 0.22s ease, border-color 0.22s ease, transform 0.16s ease;
}

.menuPage .logoutSmall {
  color: var(--muted);
  border-color: var(--line);
  background: var(--theme-subtle-panel);
}

:root[data-app-theme="warm-light"] .menuTitle::after,
:root[data-app-theme="warm-light"] .workoutTitle::after {
  background: #d7a91f;
}

:root[data-app-theme="warm-light"] .appLogo,
:root[data-app-theme="warm-light"] .loginBtn,
:root[data-app-theme="warm-light"] .loginCard .loginBtn,
:root[data-app-theme="warm-light"] .exercise button,
:root[data-app-theme="warm-light"] .showVideoBtn,
:root[data-app-theme="warm-light"] .finishWorkoutButton {
  color: #231b10;
}

:root[data-app-theme="warm-light"] .loginPage,
:root[data-app-theme="warm-light"] .appSplash {
  background:
    radial-gradient(circle at top, rgba(255, 221, 112, 0.44) 0%, transparent 44%),
    linear-gradient(180deg, #fff8e5 0%, #f2dfaa 100%);
}

:root[data-app-theme="warm-light"] .loginHero h1,
:root[data-app-theme="warm-light"] .loginCard h2,
:root[data-app-theme="warm-light"] .exercise h3,
:root[data-app-theme="warm-light"] .historyExercise h4 {
  color: var(--text);
}

:root[data-app-theme="warm-light"] .loginHero p,
:root[data-app-theme="warm-light"] .loginHint,
:root[data-app-theme="warm-light"] .previousInfo,
:root[data-app-theme="warm-light"] .previousInfo.subtle {
  color: var(--muted);
}

:root[data-app-theme="warm-light"] .loginCard,
:root[data-app-theme="warm-light"] .exercise,
:root[data-app-theme="warm-light"] .historyCard,
:root[data-app-theme="warm-light"] .finishSummaryCard,
:root[data-app-theme="warm-light"] .startWorkoutSlide {
  background: var(--card);
  border-color: var(--line);
  box-shadow: 0 16px 40px rgba(104, 78, 23, 0.14);
}

:root[data-app-theme="warm-light"] .loginCard input,
:root[data-app-theme="warm-light"] .exercise input,
:root[data-app-theme="warm-light"] .historyExercise,
:root[data-app-theme="warm-light"] .finishStatBox {
  background: rgba(255, 255, 255, 0.55);
  color: var(--text);
  border-color: var(--line);
}

:root[data-app-theme="warm-light"] .backIconBtn,
:root[data-app-theme="warm-light"] .backBtn,
:root[data-app-theme="warm-light"] .logoutSmall {
  color: var(--muted);
  border-color: var(--line);
  background: rgba(255, 255, 255, 0.42);
}

@media (max-width: 480px) {
  .themeSwitchBtn {
    top: max(14px, calc(env(safe-area-inset-top) + 10px));
    right: 14px;
    width: 44px;
    height: 44px;
  }
}

