  min-height: 72px;
  padding: 14px 16px;
  border: 0;
  background: transparent;
  color: #fff;
  display: grid;
  grid-template-columns: 1fr 34px;
  gap: 12px;
  align-items: center;
  text-align: left;
  cursor: pointer;
}

.profileMeasurementToggle strong {
  display: block;
  color: rgba(255, 255, 255, 0.94);
  font-size: 17px;
  font-weight: 1000;
  margin-bottom: 5px;
}

.profileMeasurementToggle small {
  display: block;
  color: rgba(255, 255, 255, 0.46);
  font-size: 12px;
  font-weight: 850;
  line-height: 1.28;
}

.profileMeasurementToggle em {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: rgba(127, 159, 58, 0.14);
  color: rgba(235, 250, 195, 0.96);
  font-size: 22px;
  font-weight: 900;
  font-style: normal;
}

.profileMeasurementBody {
  padding: 0 14px 14px;
}

.profileMeasurementGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.profileMeasurementGrid label,
.profileMeasurementNote {
  display: grid;
  gap: 7px;
}

.profileMeasurementGrid label span,
.profileMeasurementNote span {
  color: rgba(255, 255, 255, 0.46);
  font-size: 11px;
  font-weight: 950;
}

.profileMeasurementGrid label div {
  height: 46px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  align-items: center;
  padding: 0 12px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(0, 0, 0, 0.18);
}

.profileMeasurementGrid input {
  min-width: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: #fff;
  font-size: 16px;
  font-weight: 900;
}

.profileMeasurementGrid em {
  color: rgba(255, 255, 255, 0.42);
  font-size: 12px;
  font-weight: 900;
  font-style: normal;
}

.profileMeasurementNote {
  margin-top: 10px;
}

.profileMeasurementNote textarea {
  min-height: 76px;
  resize: vertical;
  padding: 12px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(0, 0, 0, 0.18);
  color: #fff;
  font-size: 13px;
  font-weight: 800;
  outline: none;
}

.profileMeasurementSave {
  width: 100%;
  min-height: 52px;
  margin-top: 12px;
  border-radius: 18px;
  border: 1px solid rgba(127, 159, 58, 0.24);
  background: rgba(127, 159, 58, 0.15);
  color: rgba(235, 250, 195, 0.96);
  font-size: 15px;
  font-weight: 950;
  cursor: pointer;
}

.profileMeasurementSave:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.profileMeasurementStatus {
  margin: 0;
  padding: 0 14px 14px;
  color: rgba(255, 255, 255, 0.52);
  font-size: 12px;
  font-weight: 850;
}

@media (max-width: 520px) {
  .profileMeasurementGrid {
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }

  .profileMeasurementToggle {
    min-height: 68px;
    padding: 12px;
  }

  .profileMeasurementToggle strong {
    font-size: 16px;
  }
}

/* PREMIUM AI PROFILE DASHBOARD V1 */
.profileAiDashboardCard {
  padding: 24px !important;
  overflow: hidden;
  position: relative;
  background:
    radial-gradient(circle at 14% 8%, rgba(127, 159, 58, 0.18), transparent 34%),
    radial-gradient(circle at 86% 12%, rgba(42, 171, 238, 0.10), transparent 35%),
    linear-gradient(180deg, rgba(20, 25, 20, 0.96), rgba(8, 12, 9, 0.96)) !important;
}

.profileAiDashboardCard::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(135deg, rgba(255,255,255,.055), transparent 38%);
  pointer-events: none;
}

.profileAiHero,
.profileAiStatsRow,
