/* SAFE APP ERROR TOAST */
.appErrorToast {
  position: fixed;
  left: 50%;
  bottom: max(22px, calc(env(safe-area-inset-bottom) + 14px));
  transform: translateX(-50%);
  width: min(92vw, 420px);
  padding: 15px 17px;
  border-radius: 22px;
  z-index: 20000;
  background: rgba(18, 22, 18, 0.96);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow:
    0 18px 60px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(18px);
  animation: appErrorToastIn 0.24s ease;
}

.appErrorToastTitle {
  color: rgba(255, 255, 255, 0.92);
  font-size: 15px;
  font-weight: 900;
  margin-bottom: 4px;
}

.appErrorToastText {
  color: rgba(255, 255, 255, 0.62);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
}

.appErrorToast--offline {
  border-color: rgba(212, 90, 90, 0.32);
}

.appErrorToast--savedLocal {
  border-color: rgba(127, 159, 58, 0.36);
}

.appErrorToastOut {
  opacity: 0;
  transform: translateX(-50%) translateY(14px);
  transition: 0.22s ease;
}

@keyframes appErrorToastIn {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(16px);
  }

  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}

