/* === PROGRESS HUB V274 === */
.progressHubPage {
  box-sizing: border-box;
  min-height: 100dvh;
  padding:
    max(28px, calc(env(safe-area-inset-top) + 20px))
    14px
    calc(132px + env(safe-area-inset-bottom));
  color: #f5f7f2;
  background:
    radial-gradient(circle at 50% -8%, rgba(127, 159, 58, 0.14), transparent 34%),
    linear-gradient(180deg, #081008 0%, #040704 100%);
}

.progressHubShell {
  box-sizing: border-box;
  width: min(560px, 100%);
  min-height: min(690px, calc(100dvh - 174px));
  margin: 0 auto;
  padding: 34px 18px 18px;
  border: 1px solid rgba(127, 159, 58, 0.22);
  border-radius: 30px;
  background:
    radial-gradient(circle at 18% 8%, rgba(127, 159, 58, 0.16), transparent 36%),
    linear-gradient(180deg, rgba(22, 29, 21, 0.98), rgba(6, 10, 7, 0.98));
  box-shadow:
    0 22px 58px rgba(0, 0, 0, 0.36),
    inset 0 1px 0 rgba(255, 255, 255, 0.045);
}

.progressHubHeader {
  text-align: center;
}

.progressHubHeader span {
  color: #a9d13f;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
}

.progressHubHeader h1 {
  margin: 10px 0 7px;
  color: #fff;
  font-size: clamp(28px, 8vw, 36px);
  font-weight: 800;
  line-height: 1;
}

