/* Trainer dashboard summaries v359 */
.trainerAttentionPanel {
  grid-column: 1 / -1;
  width: 100%;
  min-width: 0;
  display: grid;
  gap: 14px;
  margin: 8px 0 2px;
}

.trainerAttentionHeader {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
}

.trainerAttentionHeader > div {
  min-width: 0;
}

.trainerAttentionHeader span {
  display: block;
  margin-bottom: 4px;
  color: #a8c957;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0;
  text-transform: uppercase;
}

.trainerAttentionHeader h2 {
  margin: 0;
  color: #ffffff;
  font-size: clamp(20px, 2vw, 26px);
  line-height: 1.15;
}

.trainerAttentionHeader small {
  color: rgba(255, 255, 255, 0.48);
  font-size: 12px;
  font-weight: 700;
}

.trainerAttentionGrid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.trainerAttentionCard {
  min-width: 0;
  min-height: 92px;
  padding: 15px 16px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(22, 28, 22, 0.96), rgba(12, 16, 12, 0.96));
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.2);
}

.trainerAttentionCard > span:not(.trainerAttentionIcon) {
  min-width: 0;
  color: rgba(255, 255, 255, 0.66);
  font-size: 13px;
  font-weight: 800;
  line-height: 1.25;
}

.trainerAttentionCard strong {
  color: #ffffff;
  font-size: 27px;
  font-weight: 950;
  line-height: 1;
}

.trainerAttentionIcon {
  font-size: 17px;
  line-height: 1;
}

.trainerAttentionCard.lost .trainerAttentionIcon,
.trainerClientStatusBadge.lost {
  color: #ff756f;
}

.trainerAttentionCard.attention .trainerAttentionIcon,
.trainerClientStatusBadge.attention {
  color: #f4c95d;
}

.trainerAttentionCard.noProgram .trainerAttentionIcon,
.trainerClientStatusBadge.noProgram {
